import { describe, expect, it } from 'vitest'
import {
  canonicalGtin,
  caseGtinFromUnit,
  checkDigit,
  expandScientific,
  formatGtin,
  isValidGtin,
  lookupKeys,
  normalizeGtin,
  repairTruncated,
  toDigits,
  unitGtinFromCase,
} from './ean'

// Independently known-good codes, not generated by checkDigit itself.
const EAN13 = '5901234123457'
const EAN13_B = '4006381333931'
const EAN8 = '96385074'
const UPCA = '036000291452'

describe('checkDigit', () => {
  it('matches the published check digit for each GTIN length', () => {
    expect(checkDigit(EAN13.slice(0, 12))).toBe(7)
    expect(checkDigit(EAN13_B.slice(0, 12))).toBe(1)
    expect(checkDigit(EAN8.slice(0, 7))).toBe(4)
    expect(checkDigit(UPCA.slice(0, 11))).toBe(2)
  })
})

describe('isValidGtin', () => {
  it('accepts valid EAN-13, EAN-8 and UPC-A', () => {
    expect(isValidGtin(EAN13)).toBe(true)
    expect(isValidGtin(EAN8)).toBe(true)
    expect(isValidGtin(UPCA)).toBe(true)
  })

  it('rejects a wrong check digit', () => {
    expect(isValidGtin('5901234123458')).toBe(false)
  })

  it('rejects lengths that are not a GTIN', () => {
    expect(isValidGtin('12345')).toBe(false)
    expect(isValidGtin('')).toBe(false)
  })

  it('rejects non-digits', () => {
    expect(isValidGtin('59012341234a')).toBe(false)
  })
})

describe('toDigits', () => {
  it('strips label formatting', () => {
    expect(toDigits(' 5 901234 123457 ')).toBe(EAN13)
    expect(toDigits('5901234-123457')).toBe(EAN13)
  })
})

describe('expandScientific', () => {
  it('undoes the Excel rendering of a long barcode', () => {
    expect(expandScientific('5.90123E+12')).toBe('5901230000000')
    expect(expandScientific('8,41234E+12')).toBe('8412340000000')
  })

  it('leaves ordinary values alone', () => {
    expect(expandScientific(EAN13)).toBeNull()
    expect(expandScientific('not a number')).toBeNull()
  })
})

describe('canonicalGtin', () => {
  it('widens UPC-A to EAN-13 keeping the check digit', () => {
    expect(canonicalGtin(UPCA)).toBe('0' + UPCA)
    expect(isValidGtin(canonicalGtin(UPCA))).toBe(true)
  })

  it('narrows a zero-indicator ITF-14 back to EAN-13', () => {
    expect(canonicalGtin('0' + EAN13)).toBe(EAN13)
  })

  it('keeps a real case code at 14 digits', () => {
    const caseCode = caseGtinFromUnit(EAN13, 1)!
    expect(canonicalGtin(caseCode)).toBe(caseCode)
  })
})

describe('case and unit codes', () => {
  it('round-trips a unit EAN-13 through its case code', () => {
    const caseCode = caseGtinFromUnit(EAN13, 1)
    expect(caseCode).toBe('15901234123454')
    expect(isValidGtin(caseCode!)).toBe(true)
    expect(unitGtinFromCase(caseCode!)).toBe(EAN13)
  })

  it('does not treat a unit code as a case code', () => {
    expect(unitGtinFromCase(EAN13)).toBeNull()
    expect(unitGtinFromCase('0' + EAN13)).toBeNull()
  })
})

describe('repairTruncated', () => {
  it('restores a leading zero eaten by Excel', () => {
    expect(repairTruncated(UPCA.slice(1))).toBe('0' + UPCA)
  })

  it('returns null when no padding satisfies the check digit', () => {
    expect(repairTruncated('590123412345')).toBeNull()
  })

  it('refuses to pad a short string into a coincidentally valid GTIN', () => {
    // '123' -> '0000000000123' passes the checksum by luck. It is not a
    // barcode that lost leading zeros, so it must not be treated as one.
    expect(repairTruncated('123')).toBeNull()
  })
})

describe('normalizeGtin', () => {
  it('normalises a clean scan', () => {
    expect(normalizeGtin(EAN13)).toBe(EAN13)
    expect(normalizeGtin(UPCA)).toBe('0' + UPCA)
    expect(normalizeGtin(EAN8)).toBe(EAN8)
  })

  it('refuses to guess for scans', () => {
    expect(normalizeGtin(UPCA.slice(1))).toBeNull()
  })

  it('repairs only when the caller opts in', () => {
    expect(normalizeGtin(UPCA.slice(1), { repair: true })).toBe('0' + UPCA)
  })

  it('returns null for empty input', () => {
    expect(normalizeGtin('   ')).toBeNull()
  })
})

describe('lookupKeys', () => {
  it('tries the unit code when a case code is scanned', () => {
    const keys = lookupKeys('15901234123454')
    expect(keys[0]).toBe('15901234123454')
    expect(keys).toContain(EAN13)
  })

  it('tries the case codes when a unit code is scanned', () => {
    const keys = lookupKeys(EAN13)
    expect(keys[0]).toBe(EAN13)
    expect(keys).toContain('15901234123454')
  })

  it('falls back to the raw digits for a hand-typed code', () => {
    expect(lookupKeys('12345')).toEqual(['12345'])
  })

  it('returns nothing for input with no digits', () => {
    expect(lookupKeys('abc')).toEqual([])
  })
})

describe('formatGtin', () => {
  it('groups each length the way it reads off a label', () => {
    expect(formatGtin(EAN13)).toBe('5 901234 123457')
    expect(formatGtin(EAN8)).toBe('9638 5074')
  })
})
